package com.johnny.hotel.invoice;import com.johnny.hotel.entity.*;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class InvoiceService{private final InvoiceMapper invoices;private final FolioMapper folios;private final FolioItemMapper items;private final BookingMapper bookings;private final SysAuditLogMapper audits;private final InvoiceAccess access;private final Clock clock;
 private void require(boolean b,String m){if(!b)throw new BusinessException(m);}private void one(int n){if(n!=1)throw new BusinessException(409,"Invoice state changed");}private String clean(String s,int max,boolean required){String v=s==null?null:s.trim();if(required)require(v!=null&&!v.isEmpty(),"Required invoice field missing");if(v!=null)require(v.length()<=max,"Invoice field too long");return v;}
 @Transactional public InvoiceView issue(Long folioId,InvoiceRequests.Issue r){var actor=access.actor();access.issue(actor);require(r!=null,"Invoice request is required");String key=clean(r.getRequestKey(),100,true);invoices.ensureRequest(key);require(key.equals(invoices.lockRequest(key)),"Invoice request lock failed");var f=folios.selectByIdForUpdate(folioId);require(f!=null,"Folio does not exist");var b=bookings.selectById(f.getBookingId());require(b!=null,"Booking does not exist");var old=invoices.byRequest(key);if(old!=null){require(old.getFolioId().equals(folioId),"Request key already represents another invoice");return view(old);}require(f.getClosedTime()!=null&&Integer.valueOf(1).equals(f.getStatus())&&f.getBalanceAmount().compareTo(BigDecimal.ZERO)==0,"Invoice requires a completed and closed Folio");var source=items.selectByFolioIdForUpdate(folioId);BigDecimal sum=source.stream().map(FolioItem::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2);require(sum.compareTo(f.getTotalAmount())==0,"Folio summary changed during invoicing");var seq=new InvoiceNumber();one(invoices.sequence(seq));String number="INV-"+LocalDate.now(clock).toString().replace("-","")+"-"+String.format("%012d",seq.getId());var i=Invoice.builder().invoiceNumber(number).requestKey(key).folioId(folioId).bookingId(b.getId()).currency(f.getCurrency()).recipientName(clean(r.getRecipientName(),120,true)).recipientEmail(clean(r.getRecipientEmail(),120,false)).billingAddress(clean(r.getBillingAddress(),500,false)).taxIdentifier(clean(r.getTaxIdentifier(),80,false)).status(0).subtotal(sum).totalAmount(sum).issuedBy(actor.id()).issuedTime(LocalDateTime.now(clock)).build();one(invoices.insert(i));int line=1;for(var x:source)one(invoices.insertLine(InvoiceLine.builder().invoiceId(i.getId()).lineNumber(line++).folioItemId(x.getId()).itemType(x.getItemType()).description(x.getDescription()==null?x.getItemType():x.getDescription()).businessDate(x.getBusinessDate()).quantity(x.getQuantity()).unitPrice(x.getUnitPrice()).amount(x.getAmount()).build()));audit(actor.id(),b.getUserId(),"ISSUE_INVOICE",i.getId());return view(invoices.find(i.getId()));}
 @Transactional public InvoiceView voidInvoice(Long id,InvoiceRequests.Void r){var actor=access.actor();access.issue(actor);require(r!=null,"Void request is required");String reason=clean(r.getReason(),500,true);var i=invoices.lock(id);require(i!=null,"Invoice does not exist");if(i.getStatus()==1){require(reason.equals(i.getVoidReason()),"Invoice was voided for another reason");return view(i);}one(invoices.voidInvoice(id,actor.id(),reason));var b=bookings.selectById(i.getBookingId());audit(actor.id(),b==null?null:b.getUserId(),"VOID_INVOICE",id);return view(invoices.find(id));}
 @Transactional(readOnly=true) public InvoiceView get(Long id){var actor=access.actor();var i=invoices.find(id);if(i==null)throw new BusinessException(404,"Invoice not found");var b=bookings.selectById(i.getBookingId());if(b==null)throw new BusinessException(404,"Invoice not found");try{access.read(actor,b.getUserId());}catch(org.springframework.security.access.AccessDeniedException e){if(actor.roles().contains("CUSTOMER"))throw new BusinessException(404,"Invoice not found");throw e;}return view(i);}
 @Transactional(readOnly=true) public List<InvoiceView> byFolio(Long folioId){var actor=access.actor();var f=folios.selectById(folioId);if(f==null)throw new BusinessException(404,"Invoice resource not found");var b=bookings.selectById(f.getBookingId());if(b==null)throw new BusinessException(404,"Invoice resource not found");try{access.read(actor,b.getUserId());}catch(org.springframework.security.access.AccessDeniedException e){if(actor.roles().contains("CUSTOMER"))throw new BusinessException(404,"Invoice resource not found");throw e;}return invoices.byFolio(folioId).stream().map(this::view).toList();}
 private InvoiceView view(Invoice i){return InvoiceView.builder().invoice(i).lines(invoices.lines(i.getId())).build();}private void audit(Long actor,Long owner,String action,Long id){one(audits.insert(SysAuditLog.builder().operatorId(actor).targetUserId(owner).action(action).detail("Invoice "+id).build()));}
}
